1	// Agent-local types for the baseline and improved pipelines. These are not
2	// part of the shared contract in src/core/types.ts. Both pipelines return
3	// the same PipelineResult; fields only the improved pipeline fills are
4	// optional, so the baseline result is unchanged.
5	
6	import type {
7	  BudgetSnapshot,
8	  CompanyProvider,
9	  ProviderErrorCategory,
10	  SearchFilters,
11	} from "../data/provider";
12	import type {
13	  AnyFact,
14	  Assessment,
15	  RawCompany,
16	  Run,
17	  RunConfig,
18	  RunStep,
19	  Validation,
20	} from "../types";
21	import type { LlmCallMeta, LlmClient, LlmErrorCategory } from "./llm";
22	import type { LlmCostBasis, LlmKeySpend } from "./llm-cost";
23	import type { PipelineTracer } from "./tracer";
24	
25	// What the user asked for. Built by the app from its form.
26	export interface IcpInput {
27	  // Free text; mapped to provider industry labels via autocomplete.
28	  readonly industry: string;
29	  // Provider range strings, e.g. "51-200". Empty means any size.
30	  readonly employee_count_ranges: readonly string[];
31	  // Countries. SearchFilters takes one, so only the first is searched.
32	  readonly locations: readonly string[];
33	  // Given to the model only; the provider has no keyword filter.
34	  readonly keywords: readonly string[];
35	  // Given to the model only; neither pipeline filters on them.
36	  readonly excluded_domains: readonly string[];
37	}
38	
39	// Which pipeline produced a result.
40	export type PipelineKind = "naive_baseline" | "improved";
41	
42	export type EnrichmentStatus =
43	  | "enriched" // returned by the enrich call
44	  | "not_returned" // requested, but missing from the response
45	  | "skipped_budget" // not requested, or refused, because of the enrichment cap
46	  | "skipped_no_linkedin" // no LinkedIn URL, so it cannot be enriched
47	  | "skipped_ineligible" // improved only: rejected by validation (incl. duplicates)
48	  | "failed"; // the enrich call failed
49	
50	export interface EnrichmentOutcome {
51	  readonly status: EnrichmentStatus;
52	  // Set when the enrich call returned an error.
53	  readonly error_category?: ProviderErrorCategory;
54	}
55	
56	export type CheckSeverity = "error" | "warning";
57	
58	export type CheckFindingCode =
59	  // validateAssessment
60	  | "fit_score_out_of_range"
61	  | "criterion_score_out_of_range"
62	  | "missing_criterion"
63	  | "unexpected_criterion"
64	  | "duplicate_criterion"
65	  | "unknown_fact_reference"
66	  | "uncertain_fact_reference"
67	  // checkClaims
68	  | "no_citations"
69	  | "duplicate_citation"
70	  | "unknown_citation"
71	  | "model_fact_citation"
72	  | "non_citeable_citation"
73	  | "unsupported_number";
74	
75	// One problem found by validateAssessment() or checkClaims(). Errors make the
76	// assessment (or outreach) unusable; warnings are recorded only.
77	export interface CheckFinding {
78	  readonly code: CheckFindingCode;
79	  readonly severity: CheckSeverity;
80	  readonly message: string;
81	  readonly fact_id?: string;
82	  readonly criterion?: string;
83	}
84	
85	export interface CheckResult {
86	  // True when there are no error findings.
87	  readonly ok: boolean;
88	  readonly findings: readonly CheckFinding[];
89	}
90	
91	// What the improved pipeline's guardrails decided for one company.
92	export interface AssessmentChecks {
93	  readonly assessment: CheckResult;
94	  // Absent when the assessment failed validation or drafted no outreach.
95	  readonly claims?: CheckResult;
96	  // kept: outreach passed checkClaims. removed: it failed and was dropped
97	  // from the assessment. none: there was no usable outreach to check.
98	  readonly outreach: "kept" | "removed" | "none";
99	}
100	
101	export type AssessmentOutcome =
102	  | { readonly status: "assessed"; readonly assessment: Assessment }
103	  | {
104	      readonly status: "failed";
105	      // invalid_assessment: improved only; validateAssessment() found errors.
106	      readonly reason: "llm_error" | "malformed_output" | "truncated" | "invalid_assessment";
107	      readonly message: string;
108	      // Set when reason is "llm_error".
109	      readonly error_category?: LlmErrorCategory;
110	    }
111	  | {
112	      readonly status: "not_assessed";
113	      // llm_stopped: an earlier call failed in a way every later call would
114	      // repeat (auth failure, or rate limiting after all retries).
115	      // rejected / duplicate: improved only; validation rejected the record
116	      // (duplicate when the reason was a duplicate_domain issue).
117	      readonly reason:
118	        | "llm_call_cap"
119	        | "not_enriched"
120	        | "llm_stopped"
121	        | "rejected"
122	        | "duplicate";
123	    };
124	
125	// The model call made for one company. The same object feeds the result and
126	// the assess_company span, so the two always agree.
127	export interface LlmCallRecord extends LlmCallMeta {
128	  // 1-based position among this run's logical model calls.
129	  readonly call_number: number;
130	}
131	
132	// One company in a pipeline result. The baseline fills only the first four
133	// fields; the improved pipeline also records validation, facts and checks.
134	// Deliberately not the shared Prospect, whose validation and facts are
135	// required: the baseline has neither, and faking them would hide that.
136	export interface BaselineProspect {
137	  // The enriched record when enrichment returned it, else the search record.
138	  readonly raw: RawCompany;
139	  readonly enrichment: EnrichmentOutcome;
140	  readonly assessment: AssessmentOutcome;
141	  // Absent when no model call was made for this company.
142	  readonly llm_call?: LlmCallRecord;
143	  // Improved only: the verdict on the search record.
144	  readonly search_validation?: Validation;
145	  // Improved only: the verdict on `raw` (re-run after enrichment).
146	  readonly validation?: Validation;
147	  // Improved only: buildFacts(raw, validation); empty when rejected.
148	  readonly facts?: readonly AnyFact[];
149	  // Improved only: present when a model assessment was checked.
150	  readonly checks?: AssessmentChecks;
151	}
152	
153	// Same type, named for code that handles either pipeline.
154	export type PipelineProspect = BaselineProspect;
155	
156	// Model cost for the run, split by how each figure is known.
157	export interface LlmCostSummary {
158	  readonly gateway_reported_usd: number;
159	  readonly estimated_usd: number;
160	  // gateway_reported_usd + estimated_usd.
161	  readonly known_usd: number;
162	  readonly calls_by_basis: Readonly<Record<LlmCostBasis, number>>;
163	  // False when any call's cost is unavailable; known_usd is then a lower
164	  // bound, not the run's cost.
165	  readonly complete: boolean;
166	  // From the most recent response that carried LiteLLM key-spend headers.
167	  readonly latest_key_spend?: LlmKeySpend;
168	}
169	
170	export type PipelineIssueCode =
171	  | "industry_not_recognised"
172	  | "industry_autocomplete_failed"
173	  | "extra_locations_ignored"
174	  | "search_budget_exhausted"
175	  | "search_no_match"
176	  | "search_failed"
177	  | "enrich_budget_exhausted"
178	  | "enrich_no_results"
179	  | "enrich_partial"
180	  | "enrich_failed"
181	  | "llm_call_cap_reached"
182	  | "llm_stopped"
183	  | "llm_cost_incomplete";
184	
185	// A run-level note or failure. Per-company problems live on the prospect.
186	export interface PipelineIssue {
187	  readonly step: RunStep;
188	  readonly code: PipelineIssueCode;
189	  readonly message: string;
190	  // Provider failures.
191	  readonly error_category?: ProviderErrorCategory;
192	  // Model failures.
193	  readonly llm_error_category?: LlmErrorCategory;
194	}
195	
196	// completed_empty: the search found nothing. stopped: search failed, so the
197	// run could not continue.
198	export type PipelineStatus = "completed" | "completed_empty" | "stopped";
199	
200	// A count with the company ids behind it. Ids only, never records.
201	export interface IdCount {
202	  readonly count: number;
203	  readonly company_ids: readonly number[];
204	}
205	
206	// Guardrail outcomes of an improved run, as counts and company ids only.
207	// Plain JSON: no records, no Maps or Sets.
208	export interface ImprovedRunMetrics {
209	  // Rejected by validation for a reason other than being a duplicate.
210	  readonly rejected: IdCount;
211	  // Usable but suspicious (status "flagged" in the final validation).
212	  readonly flagged: IdCount;
213	  // Later duplicates removed (duplicate_domain), at search or after enrichment.
214	  readonly duplicates_removed: IdCount;
215	  readonly enrichment: {
216	    // Not rejected at search and has a LinkedIn URL. Ids in search order.
217	    readonly eligible: IdCount;
218	    // Sent to the enrich call, within the cap. Ids in the order sent:
219	    // "valid" companies first, then "flagged", each in search order.
220	    readonly requested: IdCount;
221	    // Returned by the enrich call. Ids in search order.
222	    readonly enriched: IdCount;
223	  };
224	  readonly assessments_failed: IdCount & {
225	    readonly by_reason: Readonly<Record<string, number>>;
226	  };
227	  // Outreach drafted by the model but removed because it failed checkClaims.
228	  readonly outreach_suppressed: IdCount;
229	  readonly claim_violations: {
230	    // Error findings from checkClaims across all drafts.
231	    readonly count: number;
232	    // Drafts with at least one violation.
233	    readonly drafts: number;
234	    readonly by_code: Readonly<Record<string, number>>;
235	    readonly company_ids: readonly number[];
236	  };
237	}
238	
239	// Citation quality of a baseline run's outreach, measured after the fact
240	// with the improved pipeline's validation and facts. Counts and ids only.
241	export interface BaselineCitationMetrics {
242	  readonly fact_provider: FactProvenance;
243	  readonly prospects: number;
244	  readonly assessed: number;
245	  readonly outreach_drafts: number;
246	  // Distinct fact ids cited across all drafts (counted once per draft).
247	  readonly cited_fact_ids: number;
248	  // Each cited id falls into exactly one of these, in this order of checks:
249	  // missing (no such fact for that company), model_provider, uncertain,
250	  // other_non_citeable (any other status outside CITEABLE_FACT_STATUSES),
251	  // citeable.
252	  readonly citeable: number;
253	  readonly missing: number;
254	  // The part of `missing` that names another company's fact.
255	  readonly cross_company: number;
256	  readonly model_provider: number;
257	  readonly uncertain: number;
258	  readonly other_non_citeable: number;
259	  // Drafts citing at least one id that is not citeable.
260	  readonly drafts_with_violations: IdCount;
261	}
262	
263	export interface PipelineResult {
264	  readonly pipeline: PipelineKind;
265	  readonly status: PipelineStatus;
266	  readonly run: Run;
267	  readonly filters: SearchFilters;
268	  readonly prospects: readonly BaselineProspect[];
269	  readonly issues: readonly PipelineIssue[];
270	  readonly usage: {
271	    readonly provider: BudgetSnapshot;
272	    readonly max_search_results: number;
273	    readonly max_enrichments: number;
274	    // Logical model calls; this is what max_llm_calls_per_run caps.
275	    readonly llm_calls: number;
276	    readonly max_llm_calls_per_run: number;
277	    // Attempts behind those calls, retries included, as reported by the
278	    // LLM client (real HTTP requests for the gateway client).
279	    readonly llm_http_attempts: number;
280	    readonly llm_cost: LlmCostSummary;
281	  };
282	  // Improved only: guardrail outcomes as counts and ids. Absent for the
283	  // baseline and for improved runs that stopped before validation.
284	  readonly metrics?: ImprovedRunMetrics;
285	}
286	
287	// Where company data came from, for buildFacts() provenance: "fixture" for
288	// FixtureProvider data, "crustdata" for real Crustdata data.
289	export type FactProvenance = "crustdata" | "fixture";
290	
291	// Dependencies for runBaselinePipeline (and the base for the improved
292	// pipeline's). fact_provider is optional here so existing baseline callers
293	// need not set it; the baseline never reads it.
294	export interface PipelineDeps {
295	  readonly provider: CompanyProvider;
296	  // The BudgetGuard the provider enforces, read to size enrich requests.
297	  // CompanyProvider does not expose one, so it is passed separately (for a
298	  // FixtureProvider, pass provider.budget).
299	  readonly budget: { snapshot(): BudgetSnapshot };
300	  readonly llm: LlmClient;
301	  // Ignored by the baseline. Allowed so one deps object can drive both
302	  // pipelines.
303	  readonly fact_provider?: FactProvenance;
304	  readonly tracer?: PipelineTracer;
305	  // Defaults to a random UUID.
306	  readonly trace_id?: string;
307	  // Milliseconds clock for step timings. Defaults to Date.now.
308	  readonly now?: () => number;
309	}
310	
311	// Dependencies for runImprovedPipeline: the same, but fact provenance must be
312	// stated explicitly. The pipeline never guesses or defaults it.
313	export interface ImprovedPipelineDeps extends PipelineDeps {
314	  readonly fact_provider: FactProvenance;
315	}
316	
317	export interface PipelineOptions {
318	  // Defaults to DEV_RUN_CONFIG.
319	  readonly config?: RunConfig;
320	  // Baseline only: which companies go to the model. Defaults to every
321	  // searched company. The improved pipeline always assesses only enriched,
322	  // non-rejected companies and ignores this option.
323	  readonly assess?: "all_searched" | "enriched_only";
324	}
