1	// Official entry point for evidence runs of the SignalScout pipelines.
2	//
3	//   npx tsx scripts/run-pipeline.ts --pipeline baseline
4	//   npx tsx scripts/run-pipeline.ts --pipeline improved --llm real --confirm-spend
5	//   npx tsx scripts/run-pipeline.ts --pipeline improved --provider crustdata --confirm-spend
6	//
7	// Options: --pipeline baseline|improved, --llm fake|real (default fake),
8	// --provider fixture|crustdata (default fixture), --confirm-spend (required
9	// with --llm real or --provider crustdata), --label <string> (default:
10	// pipeline name), --config dev|eval (default eval), --trace on|off (fixture
11	// only; crustdata runs are never traced), and for crustdata runs --industry
12	// (default "Staffing and Recruiting"), --country (default "India") and
13	// --sizes (default "11-50,51-200"). CRUSTDATA_API_KEY must be set for crustdata.
14	//
15	// Writes runs/<timestamp>-<label>.json with counts, ids, costs, issue codes,
16	// tokens and timings only: no company records, keys or headers.
17	
18	import { mkdir, writeFile } from "node:fs/promises";
19	import {
20	  FakeLlmClient,
21	  type LlmClient,
22	  type LlmRequest,
23	  type LlmResponse,
24	  type PipelineResult,
25	  PROMPT_SAFETY_RULES,
26	  PROMPT_VERSION,
27	  type PipelineTracer,
28	  computeBaselineCitationMetrics,
29	  describeIcp,
30	  noopTracer,
31	  runBaselinePipeline,
32	  runImprovedPipeline,
33	} from "../src/core/agent";
34	import { createGatewayLlmClient } from "../src/core/agent/gateway-client";
35	import { CrustdataProvider } from "../src/core/data/crustdata-provider";
36	import { FixtureProvider } from "../src/core/data/fixture-provider";
37	import { BudgetGuard, type CompanyProvider } from "../src/core/data/provider";
38	import { validateCompanies } from "../src/core/data/validation";
39	import {
40	  DEFAULT_RUN_CONFIG,
41	  DEV_RUN_CONFIG,
42	  type RawCompany,
43	  type RunConfig,
44	} from "../src/core/types";
45	import {
46	  type PostHocValidation,
47	  type ResolvedRun,
48	  buildRunIcp,
49	  exitCodeForError,
50	  exitCodeForStatus,
51	  parseRunArgs,
52	  recordSystemHashes,
53	  sha256Hex,
54	  summarizeValidation,
55	  UsageError,
56	  validateRunArgs,
57	} from "./run-metrics";
58	
59	// What the evidence ICP means in words; matches describeIcp for the open ICP.
60	const EVIDENCE_ICP_DESCRIPTION = "Companies in any industry of any size in any location.";
61	
62	// Simulated at measured Crustdata prices (USD per record).
63	const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
64	
65	const EVAL_RUN_CONFIG: RunConfig = {
66	  ...DEFAULT_RUN_CONFIG,
67	  max_search_results: 10,
68	  max_enrichments: 5,
69	};
70	
71	// Both pipelines see the same records: Crustdata's default order is not stable
72	// between calls, so crustdata runs sort by company id.
73	const CRUSTDATA_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
74	
75	type Args = ResolvedRun;
76	
77	function buildLlm(kind: Args["llm"]): LlmClient {
78	  if (kind === "fake") return new FakeLlmClient();
79	  const apiKey = process.env.LITELLM_API_KEY;
80	  if (apiKey === undefined || apiKey.trim() === "") {
81	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
82	  }
83	  return createGatewayLlmClient({ apiKey });
84	}
85	
86	// Fake-client token counts are made up; only real gateway usage is measured.
87	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
88	  return kind === "fake" ? "simulated" : "measured";
89	}
90	
91	function fileSafe(label: string): string {
92	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
93	}
94	
95	// Delegates to the real or fake client and records only the hashes of the
96	// system messages it is asked to send, never their text.
97	class HashingLlmClient implements LlmClient {
98	  readonly system_hashes = new Set<string>();
99	
100	  constructor(private readonly inner: LlmClient) {}
101	
102	  get records_llm_spans(): boolean {
103	    return this.inner.records_llm_spans;
104	  }
105	
106	  complete(request: LlmRequest): Promise<LlmResponse> {
107	    recordSystemHashes(request.messages, this.system_hashes);
108	    return this.inner.complete(request);
109	  }
110	}
111	
112	function postHocValidation(searched: readonly RawCompany[], result: PipelineResult): PostHocValidation {
113	  // The pipeline returns one prospect per searched company, in search order.
114	  return summarizeValidation(
115	    validateCompanies(searched),
116	    result.prospects.map((p) => ({
117	      company_id: p.raw.crustdata_company_id,
118	      enriched: p.enrichment.status === "enriched",
119	      delivered: p.assessment.status === "assessed",
120	    })),
121	  );
122	}
123	
124	interface ProviderSpend {
125	  search: number;
126	  enrich: number;
127	}
128	
129	function buildReport(
130	  args: Args,
131	  config: RunConfig,
132	  icp_description: string,
133	  result: PipelineResult,
134	  started_at: string,
135	  prompt: { readonly system_prompt_hashes: readonly string[] },
136	  validation: PostHocValidation,
137	  spend: ProviderSpend,
138	) {
139	  const { run, usage } = result;
140	  const fact_provider = args.provider;
141	  const simulated = args.provider === "fixture";
142	  return {
143	    started_at,
144	    label: args.label,
145	    pipeline: args.pipeline,
146	    provider: args.provider,
147	    fact_provider,
148	    tracing: args.tracing ? "on" : "off",
149	    search_sort: simulated ? null : CRUSTDATA_SEARCH_SORT,
150	    icp_description,
151	    // ICP parameters from the flags; no company data.
152	    icp_flags: simulated ? null : { industry: args.industry, country: args.country, sizes: args.sizes },
153	    config_name: args.config,
154	    config,
155	    trace_id: run.trace_id,
156	    status: result.status,
157	    counts: run.counts,
158	    cost_usd_by_step: run.cost_usd_by_step,
159	    timings_ms_by_step: run.timings_ms_by_step,
160	    cost_basis: {
161	      provider: simulated ? "simulated" : "measured",
162	      ...(simulated && { provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD }),
163	      provider_cost_usd: { search: spend.search, enrich: spend.enrich, total: spend.search + spend.enrich },
164	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
165	    },
166	    provider_usage: usage.provider,
167	    llm: {
168	      mode: args.llm,
169	      token_basis: tokenBasis(args.llm),
170	      calls: usage.llm_calls,
171	      http_attempts: usage.llm_http_attempts,
172	      input_tokens: run.counts.llm_input_tokens,
173	      output_tokens: run.counts.llm_output_tokens,
174	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
175	      estimated_usd: usage.llm_cost.estimated_usd,
176	      known_usd: usage.llm_cost.known_usd,
177	      cost_complete: usage.llm_cost.complete,
178	    },
179	    prompt_provenance: {
180	      prompt_version: PROMPT_VERSION,
181	      prompt_safety_rules_sha256: sha256Hex(PROMPT_SAFETY_RULES),
182	      system_prompt_hashes: prompt.system_prompt_hashes,
183	    },
184	    post_hoc_validation: validation,
185	    // Baseline: citations measured after the fact. Improved: its own guardrail
186	    // counts (null when it stopped before validation). Counts and ids only.
187	    citation_metrics: args.pipeline === "baseline" ? computeBaselineCitationMetrics(result, fact_provider) : null,
188	    improved_metrics: args.pipeline === "improved" ? (result.metrics ?? null) : null,
189	    issue_codes: result.issues.map((i) => i.code),
190	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
191	    prospects: result.prospects.map((p) => ({
192	      company_id: p.raw.crustdata_company_id,
193	      enrichment: p.enrichment.status,
194	      assessment: p.assessment.status,
195	      llm_call_number: p.llm_call?.call_number ?? null,
196	    })),
197	  };
198	}
199	
200	function buildProvider(args: Args, config: RunConfig): CompanyProvider & { readonly budget: BudgetGuard } {
201	  if (args.provider === "fixture") {
202	    return new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
203	  }
204	  // Presence was checked by validateRunArgs before anything was built.
205	  return new CrustdataProvider({
206	    api_key: process.env.CRUSTDATA_API_KEY ?? "",
207	    budget: new BudgetGuard(config),
208	    search_sort: CRUSTDATA_SEARCH_SORT,
209	  });
210	}
211	
212	// Tracing is loaded lazily so a crustdata or --trace off run never imports or
213	// initialises neatlogs.
214	async function withTracing<T>(
215	  args: Args,
216	  fn: (tracer: PipelineTracer) => Promise<T>,
217	): Promise<T> {
218	  if (!args.tracing) return fn(noopTracer);
219	  const { span } = await import("neatlogs");
220	  const { neatlogsTracer } = await import("../src/core/agent/neatlogs-tracer");
221	  const { closeTracing, initTracing } = await import("../src/core/observability/tracing");
222	  await initTracing({ run_label: args.label });
223	  try {
224	    return await span({ kind: "WORKFLOW", name: "signalscout_run" }, () => fn(neatlogsTracer))();
225	  } finally {
226	    await closeTracing();
227	  }
228	}
229	
230	async function main(): Promise<void> {
231	  const args = validateRunArgs(parseRunArgs(process.argv.slice(2)), process.env);
232	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
233	  const icp = buildRunIcp(args);
234	  const icp_description =
235	    args.provider === "fixture" ? EVIDENCE_ICP_DESCRIPTION : describeIcp(icp);
236	
237	  const provider = buildProvider(args, config);
238	  const llm = new HashingLlmClient(buildLlm(args.llm));
239	  const searched: RawCompany[] = [];
240	  const spend: ProviderSpend = { search: 0, enrich: 0 };
241	  const recordingProvider: CompanyProvider = {
242	    autocompleteIndustry: (query) => provider.autocompleteIndustry(query),
243	    async enrichCompanies(urls) {
244	      const res = await provider.enrichCompanies(urls);
245	      if (res.ok) spend.enrich += res.cost_usd;
246	      return res;
247	    },
248	    async searchCompanies(filters, limit) {
249	      const res = await provider.searchCompanies(filters, limit);
250	      if (res.ok) {
251	        searched.push(...res.data);
