1	// Pure helpers for scripts/run-pipeline.ts: flag parsing and validation,
2	// prompt provenance hashes and post-hoc validation counts. Nothing here
3	// returns or stores company fields or message text, only counts, company ids
4	// and hashes. Environment values are only tested for presence, never returned.
5	
6	import { createHash } from "node:crypto";
7	import type { Validation, ValidationStatus } from "../src/core/types";
8	
9	export function sha256Hex(text: string): string {
10	  return createHash("sha256").update(text).digest("hex");
11	}
12	
13	// First 12 hex characters of the sha256: enough to tell prompts apart.
14	export function shortHash(text: string): string {
15	  return sha256Hex(text).slice(0, 12);
16	}
17	
18	// Adds the short hash of every system message to `into`; text is never kept.
19	export function recordSystemHashes(
20	  messages: readonly { readonly role: string; readonly content: string }[],
21	  into: Set<string>,
22	): void {
23	  for (const m of messages) {
24	    if (m.role === "system") into.add(shortHash(m.content));
25	  }
26	}
27	
28	export interface StatusCounts {
29	  readonly valid: number;
30	  readonly flagged: number;
31	  readonly rejected: number;
32	}
33	
34	export interface ProspectFlags {
35	  readonly company_id: number;
36	  readonly enriched: boolean;
37	  readonly delivered: boolean;
38	}
39	
40	export interface PostHocValidation {
41	  readonly searched: StatusCounts;
42	  readonly enriched: StatusCounts;
43	  readonly delivered: StatusCounts;
44	  readonly wasted_enrichments: number;
45	  readonly rejected_but_enriched_ids: readonly number[];
46	  readonly rejected_but_delivered_ids: readonly number[];
47	  readonly delivered_duplicate_groups: number;
48	}
49	
50	function countStatuses(statuses: readonly ValidationStatus[]): StatusCounts {
51	  return {
52	    valid: statuses.filter((s) => s === "valid").length,
53	    flagged: statuses.filter((s) => s === "flagged").length,
54	    rejected: statuses.filter((s) => s === "rejected").length,
55	  };
56	}
57	
58	// `validations[i]` is the verdict for `prospects[i]`; both are in search order.
59	export function summarizeValidation(
60	  validations: readonly Validation[],
61	  prospects: readonly ProspectFlags[],
62	): PostHocValidation {
63	  if (validations.length !== prospects.length) {
64	    throw new Error("validations and prospects must have the same length.");
65	  }
66	  const rows = prospects.map((p, i) => ({ ...p, validation: validations[i] }));
67	  const enriched = rows.filter((r) => r.enriched);
68	  const delivered = rows.filter((r) => r.delivered);
69	  const rejected = (r: (typeof rows)[number]) => r.validation.status === "rejected";
70	
71	  // A duplicate group is identified by the first-seen record it duplicates.
72	  const groups = new Set<number>();
73	  for (const r of delivered) {
74	    for (const issue of r.validation.issues) {
75	      if (issue.code === "duplicate_domain" && issue.related_company_id !== undefined) {
76	        groups.add(issue.related_company_id);
77	      }
78	    }
79	  }
80	
81	  const enrichedCounts = countStatuses(enriched.map((r) => r.validation.status));
82	  return {
83	    searched: countStatuses(validations.map((v) => v.status)),
84	    enriched: enrichedCounts,
85	    delivered: countStatuses(delivered.map((r) => r.validation.status)),
86	    wasted_enrichments: enrichedCounts.rejected,
87	    rejected_but_enriched_ids: enriched.filter(rejected).map((r) => r.company_id),
88	    rejected_but_delivered_ids: delivered.filter(rejected).map((r) => r.company_id),
89	    delivered_duplicate_groups: groups.size,
90	  };
91	}
92	
93	// --- Flags -------------------------------------------------------------------
94	
95	export class UsageError extends Error {}
96	
97	export const EXIT_OK = 0;
98	// The run failed, or stopped early (a search failure, for example).
99	export const EXIT_FAILED = 1;
100	// Bad flags or a refused combination; nothing was run.
101	export const EXIT_USAGE = 2;
102	
103	export function exitCodeForError(err: unknown): number {
104	  return err instanceof UsageError ? EXIT_USAGE : EXIT_FAILED;
105	}
106	
107	export function exitCodeForStatus(status: "completed" | "completed_empty" | "stopped"): number {
108	  return status === "stopped" ? EXIT_FAILED : EXIT_OK;
109	}
110	
